const fs = require('fs');

const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = tokens[0];
const t = tokens[1];

let ans;
if (t === 0) {
    // Apenas o rei: N posições possíveis
    ans = n;
} else if (t === 1) {
    // Rei e torre: N posições para o rei, N-1 para a torre
    ans = n * (n - 1);
} else {
    // Duas torres com o rei entre elas:
    // com o rei na posição k, há (k-1) escolhas à esquerda e (n-k) à direita
    // soma (k-1)(n-k) para k = 1..n resulta em n(n-1)(n-2)/6
    ans = (n * (n - 1) * (n - 2)) / 6;
}

console.log(ans);
